RSpec.describe "Reservation locks seen through the entry API" do
  include_context "timekeeping entry writes"
  include_context "timekeeping entry writes without transactional fixtures"

  it "reports locked through the entry API exactly while a reservation exists and snapshots each flip" do
    company = timekeeping_arrange.company
    owner = timekeeping_arrange.user(company:, role: "owner")
    entry_id = timekeeping_arrange.entry(company:, user: owner, project: timekeeping_arrange.project(company:))
    service = timekeeping_arrange.service_identity(company:, name: "invoice-boundary",
                                                   operations: %w[prepare commit abort mark_billed detach_entries])
    operation_id = SecureRandom.uuid
    send_command = lambda do |route, extra = {}|
      body = { "invoice_id" => 501, "operation_id" => operation_id, "generation" => timekeeping_arrange.current_generation }
      post "/v1/companies/#{company}/reservations/#{route}", params: JSON.generate(body.merge(extra)),
                                                             headers: { "Content-Type" => "application/json", "Authorization" => "Bearer #{service}" }
      response
    end
    locked_in_api = lambda do
      get "/v1/companies/#{company}/entries/#{entry_id}",
          headers: { "Authorization" => "Bearer #{timekeeping_arrange.token_for(owner)}" }
      response.parsed_body.fetch("locked")
    end
    snapshots = -> { OutboxSnapshot.where(company_id: company, id: entry_id).order(:outbox_position).pluck(:locked) }

    # "From here on the entry API reports `locked: true` exactly when the entry has a reservation."
    expect(locked_in_api.call).to be(false)
    expect(send_command.call("prepare", "disposition" => "active", "entries" => [entry_id]).status).to eq(200)
    expect(locked_in_api.call).to be(true)
    # "Every reservation change that flips `locked` ... writes an audit row and an outbox snapshot row"
    expect(snapshots.call).to eq([true])
    expect(AuditEvent.where(company_id: company, entry_id:).count).to eq(1)

    expect(send_command.call("abort").parsed_body).to eq("dropped" => 1)
    expect(locked_in_api.call).to be(false)
    expect(snapshots.call).to eq([true, false])
    expect(AuditEvent.where(company_id: company, entry_id:).count).to eq(2)
  end
end

