RSpec.describe "Detach-entries service command" do
  include_context "timekeeping entry writes"
  include_context "timekeeping entry writes without transactional fixtures"

  it "detaches the agent from the path company's entries with one audit and one snapshot row per entry" do
    company = timekeeping_arrange.company
    other_company = timekeeping_arrange.company
    employee = timekeeping_arrange.user(company:, role: "employee")
    project = timekeeping_arrange.project(company:)
    own = Array.new(2) { timekeeping_arrange.entry(company:, user: employee, project:, agent_id: 77) }
    foreign = timekeeping_arrange.entry(company: other_company, user: timekeeping_arrange.user(company: other_company, role: "employee"),
                                        project: timekeeping_arrange.project(company: other_company), agent_id: 77)
    service = timekeeping_arrange.service_identity(company:, name: "agent-destroy",
                                                   operations: %w[prepare commit abort mark_billed detach_entries])
    body = JSON.generate("operation_id" => SecureRandom.uuid, "generation" => timekeeping_arrange.current_generation)
    headers = { "Content-Type" => "application/json", "Authorization" => "Bearer #{service}" }

    # "Detach-entries nulls `agent_id` on that company's entries for the agent with one audit row per entry."
    post "/v1/companies/#{company}/agents/77/detach-entries", params: body, headers: headers

    expect([response.status, response.parsed_body]).to eq([200, { "detached" => 2 }])
    expect(Entry.where(id: own).pluck(:agent_id)).to eq([nil, nil])
    expect(Entry.find(foreign).agent_id).to eq(77)
    expect(own.map { |id| AuditEvent.where(company_id: company, entry_id: id).count }).to eq([1, 1])
    expect(own.map { |id| OutboxSnapshot.where(company_id: company, id:).pluck(:agent_id) }).to eq([[nil], [nil]])
    expect(AuditEvent.where(entry_id: foreign).count).to eq(0)

    # A replay of the same operation writes no second audit row.
    post "/v1/companies/#{company}/agents/77/detach-entries", params: body, headers: headers
    expect(response.parsed_body).to eq("detached" => 2)
    expect(AuditEvent.where(company_id: company).count).to eq(2)
    expect(OutboxSnapshot.where(company_id: company).count).to eq(2)
  end
end

