RSpec.describe "Arranged reservation service identities" do
  include_context "timekeeping entry writes"

  # "A service request off the allowlist or for another company is refused,
  # and a user token never reaches these routes" can only fail in the shared
  # examples if the arranged credential really carries its company and routes.
  it "binds an arranged service identity to its company and its listed routes only" do
    company = timekeeping_arrange.company
    other_company = timekeeping_arrange.company
    service = timekeeping_arrange.service_identity(company:, name: "invoice-boundary", operations: %w[prepare])
    headers = { "Content-Type" => "application/json", "Authorization" => "Bearer #{service}" }
    request_body = lambda do |extra = {}|
      JSON.generate({ "invoice_id" => 501, "operation_id" => SecureRandom.uuid,
                      "generation" => timekeeping_arrange.current_generation }.merge(extra))
    end

    post "/v1/companies/#{company}/reservations/prepare",
         params: request_body.call("disposition" => "active", "entries" => []), headers: headers
    expect(response.status).to eq(200)

    post "/v1/companies/#{other_company}/reservations/prepare",
         params: request_body.call("disposition" => "active", "entries" => []), headers: headers
    expect([response.status, response.parsed_body]).to eq([404, { "reason" => "not_found" }])

    post "/v1/companies/#{company}/reservations/commit", params: request_body.call, headers: headers
    expect([response.status, response.parsed_body]).to eq([403, { "reason" => "forbidden" }])
  end
end

RSpec.describe "Arranged reservation reads" do
